// O(2ⁿ) subsets (each element is in or out); copying each one makes it O(n·2ⁿ) work
function allSubsets(arr) {
  if (arr.length === 0) return [[]];
  const rest = allSubsets(arr.slice(1));
  return [...rest, ...rest.map((s) => [arr[0], ...s])];
}

