function allPermutations(arr) {
  if (arr.length <= 1) return [arr];
  return arr.flatMap((x, i) =>
    allPermutations([...arr.slice(0, i), ...arr.slice(i + 1)]).map((p) => [x, ...p]));
}

questions.prompt:
What is the time complexity of each function? Justify each answer by counting how many times the innermost statement runs.

```js
// A: dependent nested loops
function triangle(n) {
  let ops = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      ops++; // runs (n-1) + (n-2) + ... + 1 + 0 times
    }
  }
  return ops; // n(n-1)/2  ->  O(n²)
}

// B: multiplicative loop variable
function doubling(n) {
  let ops = 0;
  for (let i = 1; i < n; i *= 2) {
    ops++; // i = 1, 2, 4, 8, ... while i < n
  }
  return ops; // ceil(log2 n)  ->  O(log n)
}

// C: shrinking outer loop, linear inner loop
function halvingWork(n) {
  let ops = 0;
  for (let size = n; size > 0; size = Math.floor(size / 2)) {
    for (let j = 0; j < size; j++) ops++; // n + n/2 + n/4 + ...
  }
  return ops; // < 2n  ->  O(n), not O(n log n)
}
```

