function binarySearch(arr, target) {
  let lo = 0;
  let hi = arr.length - 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) {
      lo = mid + 1; // target is right of mid: discard the left half
    } else {
      hi = mid - 1; // target is left of mid: discard the right half
    }
  }
  return -1;
}

questions.prompt:
Analyse the time and space complexity of the three Fibonacci functions below. Why is the naive one so slow, and what exactly does memoization change?

```js
// Naive: two recursive calls per call -> O(2^n) time, O(n) stack
function fib(n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}

// Memoized (top-down DP): each n is computed once -> O(n) time and space
function fibMemo(n, memo = new Map()) {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n); // cache hit: no recursion
  const value = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, value);
  return value;
}

// Bottom-up: O(n) time, O(1) space
function fibIter(n) {
  if (n === 0) return 0;
  let prev = 0;
  let curr = 1;
  for (let i = 2; i <= n; i++) [prev, curr] = [curr, prev + curr];
  return curr;
}
```

