questions.prompt:
What does **space complexity** measure? Compare the extra space used by the three functions below, and explain why `sumTo(1000000)` crashes in Node.js while `sumToIter(1000000)` does not.

```js
// O(n) extra space: n + 1 frames are on the call stack at the deepest point
function sumTo(n) {
  if (n === 0) return 0;
  return n + sumTo(n - 1);
}

// O(1) extra space: one frame with two variables, however big n is
function sumToIter(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) total += i;
  return total;
}

// O(n) extra space without recursion: the output grows with the input
function prefixSums(arr) {
  const out = new Array(arr.length);
  let running = 0;
  for (let i = 0; i < arr.length; i++) {
    running += arr[i];
    out[i] = running;
  }
  return out;
}
```

