class DynamicArray {
  constructor() {
    this.capacity = 1;
    this.length = 0;
    this.data = new Array(this.capacity);
    this.copies = 0; // instrumentation: elements moved by resizes
  }

  push(value) {
    if (this.length === this.capacity) {
      this.resize(this.capacity * 2); // rare O(n) step
    }
    this.data[this.length] = value; // usual O(1) step
    this.length++;
  }

  resize(newCapacity) {
    const bigger = new Array(newCapacity);
    for (let i = 0; i < this.length; i++) {
      bigger[i] = this.data[i];
      this.copies++;
    }
    this.data = bigger;
    this.capacity = newCapacity;
  }
}

