questions.prompt:
Explain **best-case, average-case and worst-case** complexity using linear search and quicksort as examples. Which input makes this quicksort hit its worst case, and how do real implementations avoid it? Is "worst case" the same thing as Big-O?

```js
function linearSearch(arr, target) {
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === target) return i; // best case: found at i = 0
  }
  return -1; // worst case: checked all n elements
}

// Quicksort with the LAST element as pivot (Lomuto partition)
function quickSort(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return arr;
  const p = partition(arr, lo, hi);
  quickSort(arr, lo, p - 1);
  quickSort(arr, p + 1, hi);
  return arr;
}

function partition(arr, lo, hi) {
  const pivot = arr[hi];
  let i = lo;
  for (let j = lo; j < hi; j++) {
    if (arr[j] < pivot) {
      [arr[i], arr[j]] = [arr[j], arr[i]];
      i++;
    }
  }
  [arr[i], arr[hi]] = [arr[hi], arr[i]];
  return i;
}
```

